CS_TABLES = {
    0x0000: b'\x03\x05\xff\x1f\x00\x03\x00\xa0\xfa\xfc\xba\xff\xff\xbe\x80\x00',
    0x1D60: b'\xf7\xeb\x02\xf8\xc3\xf9\xc3\x00\x00\x00\x00\x00\x00\x00\x00\xb8',
    0x6770: b'\xc3\x00\xa0\x01',
    0x6AA0: b'\x0f\xf6\xd8\x02\xc2\x98Z[\xc3\x90|\x8c|-|\x91{\xdfz`z\xecx\x98x\xdew=wev\x0fv\xc4ul\x7f&\x7f\xe2~\xd8~\xbf~\xb5~\xb5',
}


def build_boot_memory() -> bytearray:
    """The initial native memory image: zeros + DGROUP + the CS table windows."""
    data = bytearray(IMAGE_LEN)
    data[DS_BASE:DS_BASE + 0x10000] = zlib.decompress(base64.b85decode("".join(_DGROUP_Z)))
    for off, blob in CS_TABLES.items():
        data[CS_BASE + off:CS_BASE + off + len(blob)] = blob
    return data
